import{_ as a,o,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const s="/assets/235_248ede48-5d7d-4366-8a02-e7d23bf4bb1d.DoFuli50.png",d="/assets/233_blobid6.BwlzqVIe.png",i="/assets/236_88f0e15a-6dc4-4fe5-b362-63d20ffe8b59.6wSyDHVA.png",u=JSON.parse('{"title":"物理服务机器破解密码","description":"","frontmatter":{"title":"物理服务机器破解密码"},"headers":[],"relativePath":"ops-knowledge-base/dedicated-server/password-recovery.md","filePath":"ops-knowledge-base/dedicated-server/password-recovery.md","lastUpdated":1788259091000}'),l={name:"ops-knowledge-base/dedicated-server/password-recovery.md"};function n(c,e,p,_,h,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<p>当您在使用中遗忘服务器管理员（Administrator/root）密码，或需要重置密码以提升安全性时，可通过后台面板的 “破解密码” 功能，快速重置管理员密码。</p><h2 id="一、操作入口" tabindex="-1">一、操作入口 <a class="header-anchor" href="#一、操作入口" aria-label="Permalink to &quot;一、操作入口&quot;">​</a></h2><ol><li>登录平台，进入客户中心，下方**“我的订单”** 点击 <strong>“物理服务器”</strong>。或者在 <strong>“产品管理”</strong> 点击 <strong>“物理服务器”</strong>，根据机器所在地区和状态筛选。</li><li>在产品列表中，找到目标服务器，点击进入 **“产品详情”** 页面。</li><li>在 “服务器信息” 标签页下，找到并点击 **“破解密码”** 按钮，弹出 “破解密码” 操作窗口。</li></ol><p><img src="'+s+'" alt=""></p><h2 id="二、操作步骤" tabindex="-1">二、操作步骤 <a class="header-anchor" href="#二、操作步骤" aria-label="Permalink to &quot;二、操作步骤&quot;">​</a></h2><h3 id="一-默认破解管理员密码" tabindex="-1">（一）默认破解管理员密码 <a class="header-anchor" href="#一-默认破解管理员密码" aria-label="Permalink to &quot;（一）默认破解管理员密码&quot;">​</a></h3><ol><li>弹出 “破解密码” 窗口后，系统默认会对服务器的<code>Administrator</code>（Windows 系统）或<code>root</code>（Linux 系统，如 Ubuntu、CentOS 等）用户密码进行破解重置。</li><li>在 “密码” 输入框中，输入您想要设置的新密码（默认会生成随机密码）。</li></ol><h3 id="二-破解自定义用户密码-可选" tabindex="-1">（二）破解自定义用户密码（可选） <a class="header-anchor" href="#二-破解自定义用户密码-可选" aria-label="Permalink to &quot;（二）破解自定义用户密码（可选）&quot;">​</a></h3><p>若您需要破解除管理员外的自定义用户密码，勾选 “破解其他” 区域的 **“选择后将会破解自定义的用户的密码”** 复选框，后续可进一步指定需破解的自定义用户。</p><p><img src="'+d+'" alt=""></p><h3 id="三-确认破解" tabindex="-1">（三）确认破解 <a class="header-anchor" href="#三-确认破解" aria-label="Permalink to &quot;（三）确认破解&quot;">​</a></h3><p>仔细核对要设置的新密码，确认无误后，点击窗口右下角的 **“确认”** 按钮，系统开始执行密码破解重置操作。</p><p>破解成功后可在“软件信息”里，点击“*”查看最新的密码</p><p><img src="'+i+'" alt=""></p>',14)])])}const f=a(l,[["render",n]]);export{u as __pageData,f as default};
